import React, { useState, useEffect, useCallback } from 'react';
import { Container, Grid, TextField, Typography, Box, CircularProgress, Alert, Tabs, Tab } from '@mui/material';
import axios from 'axios';
import ContentCard from './ContentCard';
import InfiniteScroll from 'react-infinite-scroll-component';

const Search = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const [searchType, setSearchType] = useState('all'); // 'all', 'movie', 'tv'

  const fetchSearchResults = useCallback(async (term, pageNum = 1, type = searchType) => {
    try {
      setLoading(true);
      setError(null);

      let endpoints = [];
      if (type === 'all' || type === 'movie') {
        endpoints.push(`/api/movies/search?query=${term}&page=${pageNum}`);
      }
      if (type === 'all' || type === 'tv') {
        endpoints.push(`/api/movies/search/tv?query=${term}&page=${pageNum}`);
      }

      const responses = await Promise.all(
        endpoints.map(endpoint => axios.get(endpoint))
      );

      const newResults = responses.flatMap(response => response.data.results);
      
      if (pageNum === 1) {
        setResults(newResults);
      } else {
        setResults(prev => [...prev, ...newResults]);
      }

      setHasMore(newResults.length > 0);
      setPage(pageNum);
    } catch (err) {
      setError('Error fetching search results. Please try again.');
      console.error('Search error:', err);
    } finally {
      setLoading(false);
    }
  }, [searchType]);

  useEffect(() => {
    const delayDebounceFn = setTimeout(() => {
      if (searchTerm.trim()) {
        setPage(1);
        fetchSearchResults(searchTerm, 1);
      } else {
        setResults([]);
        setHasMore(false);
      }
    }, 500);

    return () => clearTimeout(delayDebounceFn);
  }, [searchTerm, searchType, fetchSearchResults]);

  const handleLoadMore = () => {
    if (!loading && hasMore) {
      fetchSearchResults(searchTerm, page + 1);
    }
  };

  const handleTypeChange = (event, newValue) => {
    setSearchType(newValue);
    setPage(1);
    if (searchTerm.trim()) {
      fetchSearchResults(searchTerm, 1, newValue);
    }
  };

  return (
    <Container maxWidth="xl" sx={{ mt: 4 }}>
      <Box sx={{ mb: 4 }}>
        <Typography variant="h4" component="h1" gutterBottom>
          Search
        </Typography>
        <TextField
          fullWidth
          variant="outlined"
          placeholder="Search for movies or TV shows..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          sx={{ mb: 2 }}
        />
        <Tabs
          value={searchType}
          onChange={handleTypeChange}
          sx={{ mb: 3 }}
        >
          <Tab label="All" value="all" />
          <Tab label="Movies" value="movie" />
          <Tab label="TV Shows" value="tv" />
        </Tabs>
      </Box>

      {error && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {error}
        </Alert>
      )}

      {loading && page === 1 ? (
        <Box display="flex" justifyContent="center" my={4}>
          <CircularProgress />
        </Box>
      ) : (
        <InfiniteScroll
          dataLength={results.length}
          next={handleLoadMore}
          hasMore={hasMore}
          loader={
            <Box display="flex" justifyContent="center" my={4}>
              <CircularProgress />
            </Box>
          }
          endMessage={
            <Typography variant="body1" textAlign="center" my={4}>
              {results.length === 0 && searchTerm
                ? 'No results found. Try a different search term.'
                : searchTerm
                ? 'No more results to load.'
                : 'Start searching to see results.'}
            </Typography>
          }
        >
          <Grid container spacing={3}>
            {results.map((item) => (
              <Grid item xs={12} sm={6} md={4} lg={3} key={item.id}>
                <ContentCard
                  id={item.id}
                  title={item.title || item.name}
                  posterPath={item.poster_path}
                  type={item.media_type || (item.title ? 'movie' : 'tv')}
                  rating={item.vote_average}
                />
              </Grid>
            ))}
          </Grid>
        </InfiniteScroll>
      )}
    </Container>
  );
};

export default Search;
